<?php $formProperty=$formProperty ?? null; $formId=$formId ?? 'enquiry'; ?>
<form class="enquiry-form" action="<?= url('enquiry') ?>" method="post" id="<?= e($formId) ?>">
<?= csrf_field() ?><input type="hidden" name="property_id" value="<?= e($formProperty['id'] ?? '') ?>">
<div class="honeypot" aria-hidden="true"><label>Leave this empty<input type="text" name="website" tabindex="-1" autocomplete="off"></label></div>
<div class="form-grid"><div class="field"><label for="<?= $formId ?>-name">Full name <span>*</span></label><input id="<?= $formId ?>-name" name="name" autocomplete="name" placeholder="Your full name" value="<?= e(old('name')) ?>" required minlength="2" maxlength="120"></div>
<div class="field"><label for="<?= $formId ?>-email">Email address <span>*</span></label><input id="<?= $formId ?>-email" type="email" name="email" autocomplete="email" placeholder="you@example.com" value="<?= e(old('email')) ?>" required maxlength="190"></div>
<div class="field"><label for="<?= $formId ?>-phone">Phone number <span>*</span></label><input id="<?= $formId ?>-phone" type="tel" name="phone" autocomplete="tel" placeholder="+234" value="<?= e(old('phone')) ?>" required maxlength="25"></div>
<div class="field"><label for="<?= $formId ?>-type">I’m interested in</label><select id="<?= $formId ?>-type" name="type"><?php foreach(['enquiry'=>'Property enquiry','inspection'=>'Booking an inspection','valuation'=>'A property valuation','callback'=>'Requesting a callback'] as $value=>$label): ?><option value="<?= $value ?>" <?= old('type')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div>
<?php if(!$formProperty): ?><div class="field full"><label for="<?= $formId ?>-date">Preferred inspection date <small>(optional)</small></label><input id="<?= $formId ?>-date" type="date" name="preferred_date" min="<?= date('Y-m-d') ?>" value="<?= e(old('preferred_date')) ?>"></div><?php endif; ?>
<div class="field full"><label for="<?= $formId ?>-message">How can we help? <span>*</span></label><textarea id="<?= $formId ?>-message" name="message" rows="4" placeholder="Tell us a little about what you’re looking for…" required minlength="10" maxlength="5000"><?= e(old('message', $formProperty ? 'Hello, I would like to learn more about '.$formProperty['title'].' ('.$formProperty['listing_id'].'). Please contact me to arrange a viewing.' : '')) ?></textarea></div></div>
<label class="checkbox-label"><input type="checkbox" name="consent" value="1" required><span>I agree to be contacted about my enquiry and accept the <a href="<?= url('privacy') ?>">privacy policy</a>.</span></label>
<button class="btn btn-primary form-submit" type="submit">Send enquiry <?= icon('arrow-up') ?></button><p class="form-reassurance"><?= icon('shield') ?> Your details stay with our team. Your next step stays yours.</p>
</form>
